    private final RedisGraph redisGraph;
    private RedisGraphCaches caches;

    public RedisGraphTransaction(Transaction transaction, RedisGraph redisGraph) {
        // Pass the internal connection from the transaction
        super(extractConnection(transaction));
        this.redisGraph = redisGraph;
    }

    private static Connection extractConnection(Transaction transaction) {
        // TransactionBase has protected 'connection' field
        try {
            java.lang.reflect.Field field = redis.clients.jedis.TransactionBase.class.getDeclaredField("connection");
            field.setAccessible(true);
            return (Connection) field.get(transaction);
        } catch (Exception e) {
            throw new RuntimeException("Failed to extract connection from Transaction", e);
        }
    }

