        CommandArguments args = new CommandArguments(RedisGraphCommand.QUERY)
                .add(graphId).add(query).add(Utils.COMPACT_STRING);
        return appendCommand(new CommandObject<>(args, new Builder<ResultSet>() {
            @SuppressWarnings("unchecked")
            @Override
            public ResultSet build(Object o) {
                return new ResultSetImpl((List<Object>) o, redisGraph, caches.getGraphCache(graphId));
            }
        }));
    }

